        dedupe: "ნელი და სწრაფი მაჩვენებლები: W აღნიშნავს უკვე დატოვებული ნაწილის ბოლოს, R წინ კითხულობს. მნიშვნელობა რჩება მხოლოდ მაშინ, როცა ბოლოს დატოვებულისგან განსხვავდება. ყოველი მნიშვნელობა ერთხელ იკითხება და მაქსიმუმ ერთხელ იწერება: O(n) დრო, დამატებითი მეხსიერების გარეშე.",
        partition: "L-ის მარცხნივ ყველაფერი საყრდენზე ნაკლებია, L-დან M − 1-მდე მისი ტოლია, H-ის მარჯვნივ — მეტი; M-დან H-მდე ჯერ უცნობია. ყოველი ბიჯი a[M]-ს უყურებს და უცნობ ნაწილს ერთით ამცირებს: ერთი გავლა, O(n), ადგილზე. ასე უმკლავდება სწრაფი დალაგება გამეორებებს.",
        cycle: "ყოველი მნიშვნელობა შემდეგი უჯრის ინდექსია, ამიტომ 0 ინდექსიდან სვლა აუცილებლად ციკლით მთავრდება. T ერთ უჯრას გადადის, H — ორს, ასე რომ ციკლში H ყოველ ბიჯზე ერთი უჯრით უახლოვდება T-ს და ეწევა. შემდეგ S დასაწყისიდან და H შეხვედრის წერტილიდან, თითო უჯრით, ციკლის შესასვლელთან ხვდებიან ერთმანეთს. O(n) დრო და O(1) მეხსიერება — ასე პოულობენ გამეორებულ რიცხვს n + 1 მნიშვნელობას შორის 1-დან n-მდე.",
        distinct: "R თითო სიმბოლოს ამატებს. თუ ის ფანჯარაში უკვე არსებულ სიმბოლოს იმეორებს, L ძველი ასლის მომდევნო პოზიციაზე ხტება (ლექსიკონი იმახსოვრებს, სად შეგვხვდა თითოეული სიმბოლო ბოლოს). ორივე მაჩვენებელი მხოლოდ მარჯვნივ მოძრაობს: O(n) ყველა O(n²) ქვესტრიქონის შემოწმების ნაცვლად.",
